import { dirname } from "node:path";

/** Everything a unit needs — resolved by the caller, pure here (FR-7). */
export interface UnitContext {
  /** launchd label / systemd unit name stem. */
  label: string;
  bunPath: string;
  daemonScript: string;
  workingDir: string;
  home: string;
  logsDir: string;
}

export const SERVICE_LABEL = "ai.meta-factory.reflex";

const HEADER_COMMENT =
  "generated by `reflex service install` — re-rendered on every install; manual edits are overwritten";

/** macOS LaunchAgent (the cortex/sage ecosystem pattern): RunAtLoad + KeepAlive. */
export function renderLaunchdPlist(ctx: UnitContext): string {
  return `<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<!-- ${HEADER_COMMENT} -->
<plist version="1.0">
<dict>
    <key>Label</key>
    <string>${ctx.label}</string>
    <key>ProgramArguments</key>
    <array>
        <string>${ctx.bunPath}</string>
        <string>${ctx.daemonScript}</string>
    </array>
    <key>WorkingDirectory</key>
    <string>${ctx.workingDir}</string>
    <key>RunAtLoad</key>
    <true/>
    <key>KeepAlive</key>
    <true/>
    <key>StandardOutPath</key>
    <string>${ctx.logsDir}/reflex.log</string>
    <key>StandardErrorPath</key>
    <string>${ctx.logsDir}/reflex.error.log</string>
    <key>EnvironmentVariables</key>
    <dict>
        <key>HOME</key>
        <string>${ctx.home}</string>
        <key>PATH</key>
        <string>${dirname(ctx.bunPath)}:/usr/local/bin:/opt/homebrew/bin:/usr/bin:/bin</string>
    </dict>
</dict>
</plist>
`;
}

/** Linux user unit: Restart=always, journal-logged. */
export function renderSystemdUnit(ctx: UnitContext): string {
  return `# ${HEADER_COMMENT}
[Unit]
Description=Reflex — metafactory activation runtime
After=network.target

[Service]
ExecStart=${ctx.bunPath} ${ctx.daemonScript}
WorkingDirectory=${ctx.workingDir}
Restart=always
RestartSec=2
Environment=HOME=${ctx.home}

[Install]
WantedBy=default.target
`;
}
